
function citeRefs(ids){return ids.map(id=>{const s=NF.sources.find(s=>s.id===id);return `<a class="inline-link" href="https://doi.org/${esc(s.doi)}" target="_blank" rel="noopener">${esc(s.author.split(',')[0])}${s.author.includes('&')?(s.author.split('&')[0].split(',').length<=3?' & '+esc(s.author.split('&')[1].trim().split(',')[0]):' et al.') : ''} (${s.year})</a>`}).join(' · ')}
function insightHtml(x){return `<div class="source-card"><h3>${esc(x.title)}</h3><div class="grid2 mt"><div><div class="eyebrow">What the research says</div><p>${esc(x.evidence)}</p><p class="note">${citeRefs(x.refs)}</p><h4>Why it matters</h4><p>${esc(x.why)}</p></div><div><div class="eyebrow">What to do · John’s interpretation</div><p>${esc(x.action)}</p><h4>Try it</h4><p>${esc(x.test)}</p>${btn(x.label,x.route,'blue')}</div></div></div>`}
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const routes={home:'Home',journey:'The fan journey',framework:'The Next Fan Framework',strategy:'Strategy builder',lab:'Content Lab',film:'The Film Room',research:'Research & insights',xi:"John’s Starting XI",about:"Why I’m asking this",thesis:'The thesis',sources:'Sources'};
const btn=(text,route,cls='')=>`<a class="btn ${cls}" href="#${route}">${text}<span>↗</span></a>`;
const tag=(text='Thesis evidence pending')=>`<span class="evidence">${text}</span>`;
const quote=text=>`<aside class="quote"><small>JG’S TAKE · EDITORIAL COPY</small><p>${text}</p></aside>`;
const heading=(k,t,p='')=>`<div class="page-head"><div class="eyebrow">${k}</div><h1>${t}</h1>${p?`<p>${p}</p>`:''}</div>`;
const waiting=(name='Research data')=>`<div class="waiting"><div class="symbol">＋</div><div class="eyebrow" style="justify-content:center">${name}</div><h3>Waiting for John’s research data.</h3><p class="muted">No estimates. No invented findings. This space is reserved for the evidence.</p></div>`;
const researchSplit=(text='The study examines player-personality content on MLS clubs’ Instagram accounts and its observable engagement patterns.',take='A like is not a blood oath. Your social manager might want it to be. It isn’t.')=>`<div class="grid2 mt"><div class="card"><div class="eyebrow">What the research says</div>${tag()}<p>${text} No thesis findings have been supplied.</p></div><div class="card"><div class="eyebrow">What to do with it</div><p>Identify the personality cue, interpret the observed pattern and turn it into a content idea to test. Adapt the execution to the audience and platform. Recommendations for other platforms or sports are strategic applications, not additional empirical findings.</p><small>Application framework · awaiting findings.</small>${quote(take)}</div></div>`;
function img(id,label='',height=''){const x=NF.images.find(i=>i.id===id);if(!x)return '';return `<figure class="photo"><img src="${esc(x.url)}" alt="${esc(x.alt)}" loading="lazy" ${height?`style="height:${height}"`:''}>${label?`<span class="photo-label">${label}</span>`:''}<figcaption>${esc(x.caption)} · <a href="${esc(x.source)}" target="_blank" rel="noopener">${esc(x.author)}</a> · <a href="${esc(x.licenseUrl)}" target="_blank" rel="noopener">${esc(x.license)}</a> · display crop</figcaption></figure>`}
const stageKickers=['First contact','Come back','Join in','Belong','Stick around'];
function stages(selected=-1,expanded=false){return `<div class="journey-strip ${expanded?'home-stage-strip':''}">${NF.stages.map((s,i)=>`<button class="stage-button ${selected===i?'selected':''}" data-stage="${i}" aria-pressed="${selected===i}"><span class="n">0${i+1}</span><span class="arrow">↗</span>${expanded?`<span class="stage-kicker">${stageKickers[i]}</span>`:''}<h3>${s.name}</h3><p>${expanded?s.description:s.verb}</p></button>`).join('')}</div>`}
function stageDetail(i){const s=NF.stages[i];return `<div class="stage-detail"><div class="grid2"><div><div class="eyebrow">0${i+1} / Broader fan context</div><h3>${s.verb}</h3><p>${s.description}</p><ul>${s.behaviors.map(b=>`<li>${b}</li>`).join('')}</ul></div><div>${tag(i===1?'Study focus · observable engagement':'Context only · outside this study’s outcomes')}<h4 class="mt">What to look for</h4><p>${s.metric}</p><h4>What it doesn’t prove</h4><p>${s.risk}</p>${quote(s.take)}</div></div></div>`}
function home(){const hero=NF.images.find(i=>i.id==='hazard');return `<section class="hero"><div class="hero-copy"><div class="eyebrow">A different way into the game</div><h1>I became a<br>Chelsea fan<br>because of<br><em>Eden Hazard.</em></h1><p>A player got me interested. Now I’m studying how MLS clubs put player personality into Instagram content and what engagement shows up around it.</p>${btn('Follow the fan journey','journey','blue')}<small class="muted mt">Personal motivation. Focused research. Practical sports marketing.</small></div><div class="hero-media">${hero?`<img src="${hero.url}" alt="Eden Hazard playing for Chelsea in 2012"><a class="photo-credit" href="${hero.source}" target="_blank" rel="noopener">wonker · CC BY 2.0 · display crop ↗</a>`:''}<span class="hero-tag">BEFORE THE FYP, THERE WAS HAZARD.</span><div class="hero-overlay"><div class="big-num">01 → ∞</div><h3>One player.<br>A whole new world.</h3><p>My way in was Chelsea. What’s yours?</p></div></div></section><div class="ticker"><span>Research narrowly. Apply broadly.</span><span>A research & sports marketing lab by John Gates</span></div>
<section class="section"><div class="section-top"><div class="eyebrow">01 / How it started</div><span class="meta">PERSONAL EXPERIENCE ≠ ACADEMIC EVIDENCE</span></div><div class="split"><h2>That was my fan journey.<br>What can sports marketers learn from the person behind the player?</h2><div><p>Hazard got my attention. Chelsea became my team. In between were the matches, the players, the culture and the feeling that this club somehow belonged to me.</p><div class="chips">${['Eden Hazard','Player interest','Watched Chelsea','Learned the team','Followed the culture','Identified with the club','Chelsea fan'].map(t=>`<span class="pill">${t}</span>`).join('')}</div><p class="note">An autobiographical illustration, not a finding.</p></div></div></section>
<section class="section blue-bg"><div class="eyebrow">The question behind everything</div><h2 class="question">${NF.question}</h2><p>Or, in normal-person language:</p><h3>What happens around a post when the player gets to be a person?</h3><p>This study examines how MLS clubs use player personality in team-owned Instagram content to identify engagement patterns and develop practical social media recommendations. Instagram provides a defined research environment that keeps the thesis manageable within a year. It does not limit where a marketer can test an idea.</p></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">02 / More than a seat</div><h2>FANDOM HAS<br>MORE ADDRESSES NOW.</h2></div><p>The stadium. The couch. The group chat. The feed. What does being a sports fan actually look like in 2026?</p></div><div class="montage">${img('basketball','In the stands')}${img('women','In the moment')}${img('bar','Together, elsewhere')}</div><div class="chips mt">${['Watch parties','Fan edits','Fantasy leagues','Highlights','Second screens','Athlete merchandise','Group chats'].map(x=>`<span class="pill">${x}</span>`).join('')}</div><p class="note">Photography illustrates sports settings, not evidence of audience trends or media habits.</p></section>
<section class="section dark"><div class="section-top"><div><div class="eyebrow">03 / The wider context</div><h2>A VIEW IS JUST<br>THE OPENING WHISTLE.</h2></div><p>Fandom has many stages. This study zooms into player personality, social content and engagement. The rest is context.</p></div>${stages(-1,true)}<p class="note">A broader conceptual journey, not a pathway this thesis will validate. Research focus: player personality → team-owned Instagram content → observable engagement. Project endpoint: practical application.</p>${quote('Sports fans say “we won” after contributing absolutely nothing to the victory. That level of identification is exactly why fandom is fascinating.')}</section>
<section class="section"><div class="section-top"><div><div class="eyebrow">04 / A different perspective</div><h2>EMPTY SEATS.<br>FULL FEEDS.</h2></div><p>The stands tell one story. The feed tells another. A photograph cannot tell us how many people care.</p></div><div class="grid2">${img('empty','The visible seat')}${img('stadium','The shared place')}</div><div class="split mt"><h3>Is the fan in Row 4 inherently “more of a fan” than someone 1,000 miles away?</h3><div><p>Those are different behaviors. This study examines interaction with MLS clubs’ Instagram posts. Attendance, purchasing and fan identity remain outside its measured outcomes. The photo doesn’t get to decide who counts as a fan.</p>${btn('Explore modern fandom','journey')}</div></div><div class="modern-fandom-grid mt-lg"><article class="modern-fandom-card stadium-card"><span>01 / The stadium</span><div><h3>FANDOM STILL<br>LIVES HERE.</h3><p>Tickets, chants, rituals and shared physical experiences remain powerful expressions of sports identity.</p></div></article><article class="modern-fandom-card feed-card"><span>02 / The feed</span><div><h3>THE NEW<br>FRONT DOOR.</h3><p>A highlight, athlete clip or recommendation can introduce someone to a player or team before they ever watch a full game.</p></div></article><article class="modern-fandom-card community-card"><span>03 / The group chat</span><div><h3>FANS DON’T<br>JUST WATCH.</h3><p>Memes, fantasy, reactions, debates and fan-created content turn watching sports into something fans actively contribute to.</p></div></article></div><div class="fandom-addresses-statement"><span>THE STADIUM DIDN’T DISAPPEAR.</span><strong>FANDOM JUST GOT MORE ADDRESSES.</strong></div>${quote('I found Chelsea through Eden Hazard. The next fan might find their Hazard while scrolling at 1:14 a.m. The entry point changed. The attachment can still become real.')}<p class="note">Nationals Park was photographed during a tour while the team was away. Empty seating is not evidence of an attendance problem. “Full feeds” and the three address cards are editorial framing, not measured findings.</p></section>
<section class="section blue-bg"><div class="split"><div><div class="eyebrow">From the question to the game plan</div><h2>DON’T JUST<br>CHASE THE SCROLL.</h2></div><div><p>Choose your organization, audience, engagement objective and platform. Build a player-personality content plan, with the evidence gaps left visible.</p>${btn('Build your game plan','strategy','yellow')}<p class="meta">Working tools. Provisional strategy. No invented findings.</p></div></div></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">Inside the lab</div><h2>RESEARCH WITH<br>SOMETHING TO DO.</h2></div>${btn('Explore the research','research')}</div><div class="grid3"><a href="#lab" class="card feature-card"><span class="eyebrow">Test the approach</span><h3>THE CONTENT LAB</h3><p>Fourteen player-personality angles. Practical concepts to test.</p><span>Find an angle ↗</span></a><a href="#xi" class="card feature-card"><span class="eyebrow">The final team sheet</span><h3>JOHN’S<br>STARTING XI</h3><p>Eleven places for practical recommendations as the evidence develops.</p><span>Step onto the pitch ↗</span></a><a href="#about" class="card feature-card"><span class="eyebrow">The person asking</span><h3>PLAYER. COACH.<br>FAN. MARKETER.</h3><p>Four perspectives. Research with a practical purpose.</p><span>Meet John ↗</span></a></div></section>`}
function journey(){return heading('The fan journey','BEFORE THE FYP,<br>THERE WAS HAZARD.','My path into Chelsea fandom began with a player. This is my story, not a study result.')+`<section class="section dark"><div class="split"><div>${img('hazard','The player who started it')}</div><div><div class="eyebrow">John’s mini case study</div><h2>ONE PLAYER.<br>THEN MY TEAM.</h2><div class="lab-list mt" id="story-list">${['Eden Hazard','Player interest','Watched Chelsea','Learned the team','Followed the culture','Identified with the club','Chelsea fan'].map((x,i)=>`<button style="color:inherit" data-story="${i}">0${i+1} · ${x} ↗</button>`).join('')}</div><p id="story-copy">Select a moment in my journey.</p></div></div><p class="mt">My path started with a player. That explains my interest in the human side of sports marketing. The thesis asks a narrower question about player-personality content on MLS clubs’ Instagram accounts and observable engagement. My Chelsea story is outside that sample.</p>${btn('Enter the research','research','yellow')}</section>
<section class="section"><div class="eyebrow">Then + now, not then versus now</div><h2>HOW FANDOM FOUND YOU.</h2><p>Tap the pathways that sound familiar. More than one can be true.</p><div class="then-now mt"><div><h3>THEN</h3>${['Family','Geography','Television','Local team','Favorite player','Newspaper','SportsCenter','Friends','Going to games'].map(x=>`<button data-path="${x}" aria-pressed="false">${x}</button>`).join('')}</div><div><h3>NOW</h3>${['For You Page','Athlete clips','Creators','Highlights','Memes','Algorithms','Fantasy sports','Group chats','Fan edits','Behind-the-scenes access','Viral moments'].map(x=>`<button data-path="${x}" aria-pressed="false">${x}</button>`).join('')}</div></div><p id="path-result" class="status" aria-live="polite">Your pathways will appear here. This reflection is not collected as research.</p><h3>What happens when geography is no longer the gatekeeper of fandom?</h3><p>These pathways provide context for why sports content matters. The thesis measures engagement around a defined sample of team-owned MLS Instagram content, not discovery pathways or long-term loyalty.</p></section>
<section class="section dark"><div class="eyebrow">The places fandom happens</div><h2>THE SAME SPORT.<br>DIFFERENT WAYS IN.</h2><div class="grid3 mt">${img('nfl','NFL')}${img('nhl','NHL')}${img('mls','MLS')}${img('wnba','Women’s professional sports')}${img('basketball','College basketball')}${img('stadium','European soccer')}${img('sparse','Baseball')}${img('bar','The sports bar')}</div><p class="note">Images show particular places and moments. They do not establish attendance trends or levels of fan loyalty.</p></section>
<section class="section"><div class="section-top"><div><div class="eyebrow">A little self-scouting</div><h2>ARE YOU ACTUALLY A FAN?</h2></div><p>Eleven questions. Zero authority to revoke your fan card.</p></div>${quiz()}</section><section class="section blue-bg"><div class="eyebrow">Player &gt; team?</div><h2>DO YOU LOVE THE TEAM<br>OR DO YOU JUST LOVE THAT DUDE?</h2><p>If your favorite player gets traded tomorrow, where does your loyalty go?</p><div class="poll-options">${['I stay with the team','I follow the player','Both, somehow','Honestly, it depends'].map(x=>`<button data-poll="${x}" aria-pressed="false">${x} ↗</button>`).join('')}</div><p id="poll-result" aria-live="polite">A personal reflection, not a live survey. No responses are collected or aggregated.</p><p>Athlete branding, parasocial relationships and player movement raise questions about where attachment lives. We are not assuming the answer.</p></section><section class="section"><div class="eyebrow">Participatory culture</div><h2>FANS AREN’T JUST THE<br><s>AUDIENCE.</s> PARTICIPANTS.</h2><p>Fan edits. Reaction videos. Memes. Duets. Stitches. Predictions. Fantasy sports. Debates. Creator analysis. Inside jokes. Traditions.</p><p>Creating fan content, joining a community, taking part in an activation, attending an event or purchasing goes beyond interacting with the original post. Those deeper actions are participation. Viewing, liking, commenting and sharing the original post are engagement. This study focuses on engagement.</p>${researchSplit('The thesis examines observable engagement. Participation, identity and loyalty are outside its measured outcomes.','At some point you stop consuming the joke and become part of the joke.')}</section>`}
function framework(){return heading('Developed by John Gates','THE NEXT FAN FRAMEWORK.','The broader fan journey provides context. The working research framework focuses on player personality, team-owned Instagram content and observable engagement, then turns patterns into practical strategy.')+`<section class="section"><div class="framework-wrap"><div class="personalization">FAN JOURNEY · CONTEXT, NOT THE STUDY OUTCOMES</div>${stages(1)}<div class="backpaths"><span>↔ Return to earlier stages</span><span>↗ Skip a stage</span><span>↘ Follow an athlete, not a team</span><span>↘ Leave the journey</span></div><div id="stage-panel">${stageDetail(1)}</div></div><p class="note">These stages are background, not a conversion sequence tested by this thesis. Click a stage for its meaning and limits. Engagement is the research focus; participation, identity and loyalty require different evidence.</p><div class="status"><strong>Research → Find the pattern → Interpret the pattern → Turn it into strategy → Show how to apply it.</strong><p>Study: player personality → team-owned MLS Instagram content → observable engagement. Application: adapt a supported insight into a testable content recommendation, with limits attached.</p></div>${researchSplit()}</section>
<section class="section dark"><div class="eyebrow">The scoreboard isn’t the whole game</div><h2>CONGRATS ON THE VIEWS.<br>NOW WHAT?</h2><div class="grid2 mt"><div><span class="evidence">Illustrative numbers only · not actual results</span>${[['1,400,000','views'],['87,000','likes'],['6,400','shares']].map(([n,t])=>`<div class="metric-row"><span class="metric-num">${n}</span><span>${t}</span></div>`).join('')}</div><div><ul class="checklist">${['What personality cues are present?','Which public metrics are visible?','Were posts observed at comparable ages?','How do format and club context differ?','Is the pattern repeated across comparable posts?','What alternative explanations remain?','What could a marketer test next?'].map(x=>`<li>${x}</li>`).join('')}</ul></div></div><h2 class="mt-lg">ATTENTION ≠ LOYALTY</h2><p>Likes, comments and views describe interaction. They do not establish loyalty, identity, purchases or a causal effect of player personality. Public counts cannot identify unique fans or show why they responded.</p></section>
<section class="section"><div class="eyebrow">An extremely expensive metaphor</div><h2>THE $17 HOT DOG TEST.</h2><p>A context exercise in different behaviors. Tap a step to see what the study can and cannot measure.</p><div class="hotdog-track">${['Saw a video','Watched another','Followed','Commented','Joined the community','Watched a game','Bought a jersey','Bought a ticket','Paid an offensive amount for stadium food','Still came back'].map((x,i)=>`<button data-hotdog="${i}" class="${i===0?'active':''}"><span>${String(i+1).padStart(2,'0')}</span>${x}</button>`).join('')}</div><div id="hotdog-detail" class="status" aria-live="polite">Attention: a first exposure. It tells us a video was encountered, not that a fan was created.</div><p class="note">Illustrative teaching pathway, not a validated scale. $17 is a joke, not a quoted price. People can skip steps, return or leave. Commercial actions depend on access, money and geography; spending is not required to be a fan.</p>${quote('A comment and a stadium hot dog are different outcomes. My thesis does not need a concessions budget.')}</section>`}
const orgs=['Professional Team','College Athletics','League','Athlete','Sports Brand','Sports Media Company'],audiences=['Existing fans','Casual fans','Young fans','Fans outside your geographic market','Fans of an individual athlete','People unfamiliar with your sport'],goals=['Engagement','Conversation','Content viewing','Sharing'],assets=['Player interviews','Teammate interactions','Behind-the-scenes access','Routines and hobbies','Humor','Player voice'];
const select=(id,label,options)=>`<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${options.map(x=>`<option>${x}</option>`).join('')}</select></div>`;
function strategy(){return heading('The sports marketing strategy builder','YOUR NEXT FAN.<br>YOUR GAME PLAN.','Choose a player-personality angle and an observable response to aim for. Get a practical planning draft you can adapt and test.')+`<section class="section"><form id="strategy-form"><div class="controls">${select('org','Who are you?',orgs)}${select('audience','Who are you trying to reach?',audiences)}${select('goal','Which engagement objective?',goals)}${select('platform','Where will you use the idea?',Object.keys(NF.platforms))}<fieldset class="field"><legend>What player-personality content can you access? Choose at least one.</legend><div class="checks">${assets.map((x,i)=>`<label class="check"><input type="checkbox" name="assets" value="${x}" ${i===0?'checked':''}>${x}</label>`).join('')}</div></fieldset></div><div class="btn-row mt"><button class="btn blue" type="submit">Build my game plan <span>↗</span></button><button class="btn" type="reset">Reset</button></div><p class="note">Literature-informed planning, with creative choices to test. The empirical study is limited to MLS Instagram content. Plans for other channels and sports are adaptations to test, not proven effects.</p><p id="form-error" role="alert"></p></form><div id="game-plan" aria-live="polite"></div></section>`}
function createPlan(org,audience,goal,chosen,platform='Instagram'){
const approaches={Engagement:'Choose one clear personality moment and an intended response before deciding the format.',Conversation:'Ask one answerable question connected to what the player actually said or did.', 'Content viewing':'Give the moment a clear setup and payoff. Keep enough context for a new viewer.',Sharing:'Create a moment someone might want to pass along. Do not assume sharing counts are publicly available.'};
const audienceTip={'Existing fans':'Shared context can help, but explain an inside joke before asking people to join it.','Casual fans':'Introduce the player and situation without requiring roster homework.','Young fans':'Keep prompts age-appropriate and avoid soliciting personal information.','Fans outside your geographic market':'Make local references understandable and consider language and time zones.','Fans of an individual athlete':'Let the player’s voice lead while giving teammates and the club useful context. Do not assume attachment transfers.','People unfamiliar with your sport':'Explain the situation simply. The personality should be understandable without knowing every rule.'}[audience];
const concepts={'Player interviews':'One player, one specific question, one answer in their own words.','Teammate interactions':'Two teammates explain a shared routine or harmless disagreement.','Behind-the-scenes access':'A consent-cleared player-led look at a club routine.','Routines and hobbies':'A recurring player prompt about a volunteered interest.','Humor':'A player-led joke or reaction with context, never a manufactured embarrassment.','Player voice':'Let the player choose a topic they want fans to understand.'};
const metric={Engagement:'Record public likes and comments separately, plus views where visible. Use shares only where publicly available.',Conversation:'Compare public comment counts on comparable posts. Counts alone do not establish sentiment or community membership.', 'Content viewing':'Compare publicly visible views only across formats with comparable definitions. Missing views are not zero views.',Sharing:'Use public share counts only where visible and consistently available. If unavailable, record missing data and choose another observable measure.'}[goal];
return {org,audience,goal,chosen,platform,items:[
['Content objective',`${goal}: an engagement objective, not a promise of loyalty or conversion.`],
['Personality-led approach',`${approaches[goal]} ${audienceTip}`],
['Repeatable concepts',chosen.map(x=>concepts[x]).join(' • ')],
['Why this is a starting point',`For a ${org.toLowerCase()} reaching ${audience.toLowerCase()}, connect a real player interest, voice or relationship to the intended response. This is a planning rationale, not an observed effect.`],
['Platform adaptation',`${platform}: ${NF.platforms[platform]}`],
['A practical content plan','Choose a willing player and one repeatable prompt. Capture a small batch with a phone and clear audio where appropriate. Prepare captions or text context. Schedule comparable posts, record publication and observation dates, then review what happened before repeating the format.'],
['Creative direction','Match the concept to the player: humor for someone who enjoys it, a hobby for someone who wants to share it, teammate interaction where the relationship is comfortable. Performance can lead when the sporting moment is the point. Do not force personality into every post.'],
['Observable measures',metric+' Record unavailable counts as missing, not zero. Account for post age, format and club context before comparing.'],
['For organizations with internal analytics','Watch time, retention, saves and reach may support your own evaluation if you have access. They are not assumed public measures or additional thesis outcomes. Keep platform definitions separate.'],
['What to test next','Change one execution choice at a time where practical. Compare like with like, look for repeated patterns and consider match results, player prominence and distribution as alternative explanations. Associations do not establish causation.'],
['Limits and permissions','Get player consent, respect privacy and media rights, and plan moderation. MLS Instagram evidence cannot establish the same effects on another platform, in another sport or for an individual athlete account.'],
['Literature behind the approach','Athlete content and engagement: Doyle et al. (2022), https://doi.org/10.1080/16184742.2020.1806897. Club content strategy: Annamalai et al. (2021), https://doi.org/10.1016/j.jretconser.2021.102648. Publisher credibility: Na et al. (2020), https://doi.org/10.1080/16184742.2019.1662465. These contexts inform the plan; they do not validate this exact campaign.'],
['Measurement foundation','Kennedy et al. (2021), https://doi.org/10.32731/SMQ.304.1221.02, informs the measurement perspective. Practical application: compare category medians within the same club and format at a consistent post age. If using (likes + comments) / followers × 100, label it a follower-normalized interaction rate, record follower count at observation and keep it separate from reach-based rates. It is not a unique-fan percentage.'],
['Client-session decisions','Agree on the player, content owner, primary metric, comparison posts and review date. After review, record what to keep, change or stop, with the evidence and alternative explanations beside the decision.'],
['Evidence status','Research-informed strategic application · original thesis findings pending. The supplied literature supports the planning questions and categories; this specific recommendation, schedule and platform adaptation require testing. No performance uplift or fan conversion is claimed.']
]};}

let latestPlan=null;
function planHtml(p){return `<div class="plan"><div class="plan-head"><div><div class="eyebrow">${esc(p.org)} / ${esc(p.goal)}</div><h2>YOUR GAME PLAN.</h2></div><button class="btn yellow" id="export-plan">Download game plan ↓</button></div><div class="status">RESEARCH-INFORMED PLANNING DRAFT · Audience: ${esc(p.audience)} · Platform: ${esc(p.platform)} · Thesis evidence pending</div><div class="plan-grid">${p.items.map(([k,v])=>`<div class="plan-cell"><h4>${k}</h4><p>${esc(v).replace(/https:\/\/doi\.org\/[^\s]+/g,u=>`<a class="inline-link" href="${u.replace(/\.$/,'')}" target="_blank" rel="noopener">${u.replace(/\.$/,'')}</a>`)}</p></div>`).join('')}</div></div>`}
function lab(){return heading('The Content Lab','SAME SPORT.<br>FOURTEEN DIFFERENT ANGLES.','Explore player personality as a marketing asset. These categories draw on athlete self-presentation and branding research. The prompts are original planning examples to test, not thesis findings. A player appearing in a highlight is not automatically personality content: look for voice, interests, humor, relationships or reactions beyond performance.')+`<section class="section"><div class="lab"><div class="lab-list" aria-label="Content formats">${NF.formats.map((f,i)=>`<button data-format="${i}" class="${i===0?'active':''}" aria-pressed="${i===0}">${f[0]} ↗</button>`).join('')}</div><div id="format-panel">${formatDetail(0)}</div></div><div class="mt-lg"><div class="eyebrow">Research narrowly. Apply broadly.</div><h2>DON’T BUILD FOR THE APP.<br>BUILD FOR THE FAN.</h2><p>Keep the player insight and intended response. Change the execution to suit the channel and audience. Platform-proof means adaptable thinking, not a guarantee that a format will work everywhere.</p><div class="status">Application concept: two teammates explain their pre-match playlists. The versions below are creative options to test, not evidence of platform-specific effects. Instagram is the research environment; other channels are applications.</div><div class="plan-grid">${Object.entries(NF.platforms).map(([name,copy])=>`<div class="plan-cell"><h4>${name}</h4><p>${copy}</p></div>`).join('')}</div><p class="note">Findings will describe the MLS Instagram sample studied. Adaptations for other sports, athlete brands and channels require their own evaluation.</p></div></section>`}
function formatDetail(i){const f=NF.formats[i];return `<div class="eyebrow">Format ${String(i+1).padStart(2,'0')} / 14</div><h2>${f[0].toUpperCase()}</h2><div class="mt">${tag('Research-informed category · creative example to test')}</div><div class="plan-grid mt">${[['Intended engagement · not a predicted result',f[1]],['Potential audience',f[2]],['Creative rationale · to test',f[3]],['Potential downside',f[4]],['Observable measures where available',f[5]],['Example concept · not a real case study',f[6]],['Academic foundation',`Athlete self-presentation and brand-image concepts inform this category: ${citeRefs(NF.formatRefs[i])}. The exact prompt is John’s creative interpretation, not a tested recipe or an MLS club finding.`],['Try it in a brief',`Choose a willing player, define the personality cue and pair the concept with a comparable post for review. ${btn('Open Strategy Builder','strategy')}`]].map(([k,v])=>`<div class="plan-cell"><h4>${k}</h4><p>${v}</p></div>`).join('')}</div>`}
const questions=['Do you watch full games?','Do you watch highlights?','Do you follow individual players?','Do you follow the team?','Have you bought merchandise?','Have you attended a game?','Do you participate in fan communities?','Do you create or share sports content?','Do you play fantasy sports?','Would you watch this team if its star player left?','Do you know enough obscure roster information that you should probably go outside?'];
function quiz(){return `<div class="status">Exploratory engagement feature. Not a validated academic measurement instrument. Answers stay in this page and are not collected.</div><form id="quiz-form">${questions.map((q,i)=>`<div class="quiz-row"><label for="q${i}">${String(i+1).padStart(2,'0')} / ${q}</label><select id="q${i}" required><option value="">Choose</option><option value="1">Yes</option><option value="0">No</option></select></div>`).join('')}<button class="btn blue mt" type="submit">Give me my scouting report ↗</button><button class="btn mt" type="reset">Start again</button></form><div id="quiz-result" aria-live="polite"></div>`}
function film(){return heading('The Film Room','LET’S WATCH THE TAPE.','A personal starting point for the question, followed by practical content analysis. This Chelsea example is outside the MLS Instagram research sample.')+`<section class="section" id="hazard-case"><div class="eyebrow">Personal illustration · JG’s take</div><h2>TAPE 001: EDEN HAZARD</h2><p class="lead">When the player is the doorway to the club.</p><div class="film"><div class="tape-media"><div class="film-screen"><video controls playsinline preload="metadata" width="576" height="768" aria-label="Tape 001: Eden Hazard" aria-describedby="tape-description"><source src="media/eden-hazard.mp4" type="video/mp4">Your browser does not support this video. <a href="media/eden-hazard.mp4">Open the Eden Hazard video</a>.</video></div><p class="note" id="tape-description">A Hazard edit combining discussion, match footage and memorable moments. Use the player controls for playback and sound.</p><div class="card mt"><div class="eyebrow">John’s personal connection</div><h3>HAZARD LEFT. I STAYED.</h3><p>Hazard was my entry point into Chelsea. What began as interest in one player became interest in the club. Hazard eventually left. I stayed.</p><p>Apparently, my Chelsea membership did not come with a player-transfer clause.</p><p>That experience explains my interest in the person behind the player. The thesis asks a narrower question about player-personality content and observable engagement on MLS clubs’ Instagram accounts.</p><small>My experience is a personal illustration, not proof that every fan follows this pathway.</small></div></div><div class="film-panel"><div class="eyebrow">John’s breakdown</div><p class="note">Personal interpretation and sports-marketing recommendations. No audience outcomes are claimed.</p><h4>The player as the hook</h4><p>Hazard is my reason to watch. This edit mixes sporting performance, discussion and memorable moments. That is useful creative context, but star power and skill alone do not make a post player-personality content.</p><h4>Possible engagement</h4><p>The changing scenes and discussion give me reasons to keep watching. That is my reading of the edit. No verified likes, comments, views or shares have been supplied, so I cannot say how other viewers responded.</p><h4>Personality versus performance</h4><p>A highlight shows what a player can do. Personality content shows something about who they are: their voice, humor, interests or relationships. Mixed posts need a consistent coding rule. This edit is not being presented as a coded MLS research observation.</p><h4>My Chelsea connection</h4><p>Eden Hazard was my original entry point into Chelsea fandom. Interest in the individual player eventually expanded into identification with Chelsea itself. That is my experience, not a universal fan pathway.</p><h4>What my story cannot prove</h4><p>Hazard left. I stayed. That is autobiography, not evidence that player content creates loyalty. It does not establish engagement effects, purchasing behavior or a general pathway from athlete interest to team identity.</p><h4>Creative strengths · my reading</h4><p>In my reading, star power and recognizable personalities create an immediate hook. Storytelling gives the spectacular athletic moments context, while short-form editing keeps moving between discussion and action. Nostalgia adds emotional connection for someone like me. The skill is also accessible: you do not need extensive football knowledge to find a moment compelling. These are creative strengths I see, not verified performance findings.</p><h4>What I’d change</h4><p>My application concept: pair a sporting moment with a player’s own voice, then give viewers one relevant question to answer.</p><p><strong>PLAYER MOMENT → PERSONAL CONTEXT → ONE CLEAR PROMPT → OBSERVE THE RESPONSE</strong></p><p>For a current club, I’d try a player-led explanation of a celebration or a teammate exchange around a match moment. Adapt it into a visual story, short clip or quote depending on the channel. This is creative direction to test, not a claim that it will increase engagement.</p><h4>Research connection</h4><p>My experience motivated the question; the MLS Instagram sample must support the conclusions. The study examines personality cues in team-owned posts and associated observable engagement patterns. This Hazard edit is neither a sample post nor empirical support for that relationship.</p><small>Conceptual interpretation to investigate, not causal proof from this video.</small><div class="card mt"><div class="eyebrow">What the research says</div><p>This case study supplies no research findings or verified audience analytics. John’s story and recommendations remain separate from academic evidence. The thesis will examine the narrower MLS Instagram question. This story will remain separate from its findings.</p></div></div></div><div class="mt-lg"><div class="eyebrow">The future case-study shelf</div><h2>EVERY SPORT HAS A STORY.</h2><p>MLS Instagram is the empirical research setting. Other sports on this shelf are future application examples, not extensions of the study sample. No completed examples are claimed.</p><div class="chips">${NF.leagues.map(x=>`<button class="pill" data-case="${x}">${x} ↗</button>`).join('')}</div></div></section>`}
function research(){return heading('Research & insights','RESEARCH WITH<br>SOMETHING TO DO.','Start with a useful principle. Build a brief, try a content idea and decide what to measure. The academic foundation is here when you need it.')+`<section class="section"><div class="status"><strong>25 academic sources. One focused thesis.</strong><p>Existing literature informs the applications below. John’s study remains MLS clubs’ Instagram accounts, player-personality content and observable engagement patterns. Its methodology and original findings are still pending.</p><p>Research summaries draw on the supplied bibliography. Creative recommendations are John’s interpretations to test, not interventions proved by every cited paper. Older research supplies conceptual context; it does not prescribe current platform tactics.</p></div>${NF.insights.map(insightHtml).join('')}<div class="btn-row mt">${btn('Explore all 25 sources','sources','blue')}${btn('Read the thesis scope','thesis')}</div><div class="mt-lg"><h2>JOHN’S STUDY: STILL IN PROGRESS.</h2><p>The literature provides a foundation. The MLS club sample will supply the project’s own evidence. No original engagement results are claimed here.</p></div></section>`}

function xi(){return heading('John’s Starting XI','11 PLACES FOR<br>PRACTICAL STRATEGY.','The formation stays. Recommendations earn their place through evidence, interpretation and useful application.')+`<section class="section"><div class="grid2"><div class="pitch"><div class="formation">${Array.from({length:11},(_,i)=>`<button class="player" data-player="${i+1}"><span class="shirt">${String(i+1).padStart(2,'0')}</span><span>Strategy idea</span></button>`).join('')}</div></div><div><div class="eyebrow">4–3–3 / Developed by John Gates</div><h2>NO ONE MAKES<br>THE XI ON HYPE.</h2><p>Each position can hold a practical recommendation tied to a verified finding and its limits. Eleven is the presentation format, not a required number of discoveries. Positions stay empty unless the evidence supports filling them.</p>${tag('All eleven principles awaiting research')}<ul class="checklist">${['The recommendation','What the research found','Interpretation and limits','What a sports marketer could test','Observable measures','Platform adaptation','JG’s take'].map(x=>`<li>${x}</li>`).join('')}</ul><p class="note">The formation is a visual navigation device. It does not rank the strength of evidence or imply tactical relationships.</p></div></div></section>`}
function about(){return heading('Player / Coach / Fan / Marketer','WHY I’M ASKING<br>THIS QUESTION.','I know sports as a player, coach and fan. I want to turn that perspective into research a sports marketer can actually use.')+`<section class="section"><div class="split"><div><h2>JOHN GATES.</h2><p>I played Division I college soccer at Loyola Chicago and Lindenwood, and I’ve continued playing competitive soccer beyond college. I also coach soccer, which means I spend plenty of time around young athletes whose sports world looks different from the one I grew up in.</p><p>I’m pursuing a master’s degree in digital and social media marketing at Lindenwood University. I want to work for a professional sports organization and may eventually build my own sports marketing firm. THE NEXT FAN is my applied master’s project and a place to demonstrate the research, analysis and strategic thinking I could bring to that work.</p><p>And I’m a fan. Hazard made me care about Chelsea. That personal experience made me curious about athletes as people, not only performers. It explains why I’m asking. The MLS Instagram research will determine what I can conclude.</p></div><div class="portrait"><div id="portrait-preview"><strong>JG</strong><p>John’s professional photo</p><small>Portrait to be supplied. Preview a replacement below.</small></div><label for="portrait-upload" class="btn mt">Choose photo preview</label><input id="portrait-upload" type="file" accept="image/*" hidden><p class="note">Private, session-only preview. Send John’s final photo in chat to add it to the site permanently.</p></div></div><div class="grid2 mt-lg">${[['PLAYER','I understand the sport from inside the game. The details on the field and the story around it both matter.'],['COACH','I work with younger athletes who are growing up with a different set of pathways into sport.'],['FAN','I know what it feels like when a team becomes “we,” even when I have no business taking credit.'],['MARKETER','I want to identify meaningful content patterns and translate them into creative direction, repeatable formats and plans an organization can test.']].map(([t,p])=>`<div class="card"><div class="eyebrow">One of four lenses</div><h3>${t}</h3><p>${p}</p></div>`).join('')}</div><div class="mt-lg"><div class="eyebrow">The question behind the question</div><h2>WHAT SHOULD A MARKETER<br>ACTUALLY DO WITH THIS?</h2><p>The goal is to connect research to execution: analyze professional content, identify a pattern, interpret it carefully and build a usable recommendation. A team, athletic department, athlete, agency or marketing firm could adapt the framework to its own audience and resources. Those adaptations need testing in their own settings. THE NEXT FAN is where I can show that process through an applied master’s project.</p></div></section>`}
function thesis(){return heading('The academic page','YES, THERE’S<br>AN ACTUAL THESIS.','For anyone who looked at the $17 hot dog graphic and thought, “But where’s the methodology?” Welcome.')+`<section class="section academic"><div class="eyebrow">John Gates / Master’s thesis project</div><h2>Research question</h2><p>${NF.question}</p><p>This study examines how MLS clubs use player personality in team-owned Instagram content to identify engagement patterns and develop practical social media recommendations for professional sports organizations.</p><div class="status"><strong>Instagram is the research environment. Application is the endpoint.</strong><p>MLS and Instagram bound the study so it remains manageable within one year. Public likes and comments, views where visible and shares where publicly available are candidate measures. The final sample, time window, coding rules and consistently available measures must be specified in the methodology; they have not been supplied.</p><p>The study examines associations, not causal effects. It does not measure participation, fan identity, purchasing or long-term loyalty. Recommendations for other platforms and sports are practical adaptations, not additional empirical findings.</p></div><div class="status">Thesis in development. The completed document and chapters have not yet been supplied.</div>${[['Abstract','abstract'],['Literature Review Overview','literature'],['Methodology','methodology'],['Findings','findings'],['Discussion','discussion'],['Limitations','limitations'],['Future Research','future']].map(([t,k])=>`<details><summary>${t}</summary><p>${NF.thesis[k]?esc(NF.thesis[k]):`Waiting for John’s ${t.toLowerCase()}. No ${t.toLowerCase()} has been invented for this website.`}</p></details>`).join('')}<details><summary>References</summary><p>The research library contains the 25 supplied academic references, grouped by theme with DOI links and application context. These sources are distinct from the thesis’s original findings.</p>${btn('Open sources','sources')}</details><div class="mt"><button class="btn" disabled>Download full thesis · forthcoming</button><p class="note">The download becomes available when John supplies the completed thesis.</p></div></section>`}
function sources(){return heading('Academic research library + credits','SHOW YOUR SOURCES.','25 supplied academic sources, grouped by what they help explain. Recent studies inform the discussion; older work supports concepts and research design.')+`<section class="section"><div class="controls"><div class="field"><label for="source-search">Search author, title or finding</label><input type="search" id="source-search" placeholder="Search the research library"></div>${select('source-theme','Filter by theme',['All themes',...NF.sourceThemes])}</div><p class="note">${NF.sources.length} academic references supplied by John. Summaries describe relevance and limits, not a completed systematic review. Image credits are separate from research evidence.</p><div id="source-results" class="mt">${sourceResults()}</div><div class="mt-lg"><div class="eyebrow">Photography, not evidence</div><h2>IMAGE CREDITS.</h2><p>Images are reused under the licenses below. Display crops may differ from the original. Share-alike image derivatives retain the original license. Team, league and athlete appearances do not imply affiliation.</p>${NF.images.map(x=>`<div class="source-card"><h4>${esc(x.alt)}</h4><p>${esc(x.caption)}</p><small><a href="${x.source}" target="_blank" rel="noopener">Source photograph</a> · ${esc(x.author)} · <a href="${x.licenseUrl}" target="_blank" rel="noopener">${x.license}</a> · display crop</small></div>`).join('')}</div></section>`}
function sourceResults(q='',theme='All themes'){const list=NF.sources.filter(s=>(theme==='All themes'||s.theme===theme)&&JSON.stringify(s).toLowerCase().includes(q.toLowerCase()));return list.length?NF.sourceThemes.map(t=>{const group=list.filter(s=>s.theme===t);return group.length?`<details class="research-group" ${q||theme!=='All themes'?'open':''}><summary>${esc(t)} (${group.length})</summary><ol>${group.map(s=>`<li class="source-card"><p><strong>${esc(s.author)} (${esc(s.year)}).</strong> ${esc(s.title)} <em>${esc(s.journal)}</em> <a class="inline-link" href="https://doi.org/${esc(s.doi)}" target="_blank" rel="noopener">${esc(s.doi)}</a></p><p>${esc(s.finding)}</p><small>${esc(s.status)} · Used for: ${esc(s.whereUsed)}</small></li>`).join('')}</ol></details>`:''}).join(''):`<p role="status">No sources match this search. Try an author, topic or another theme.</p>`}
const views={home,journey,framework,strategy,lab,film,research,xi,about,thesis,sources};
function render(){let route=location.hash.slice(1)||'home';if(!views[route])route='home';$('#main').innerHTML=(route!=='home'?'<div class="research-banner">WORKING THESIS LAB · Conceptual framework and editorial tools. Thesis findings pending.</div>':'')+views[route]();document.title=`${routes[route]} | THE NEXT FAN`;document.querySelectorAll('nav a').forEach(a=>a.classList.toggle('active',a.hash==='#'+route));$('#menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false');window.scrollTo(0,0);wire(route)}
function modal(html){$('#detail-body').innerHTML=html;$('#detail').showModal()}
function download(name,text){const u=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function wire(route){document.querySelectorAll('[data-stage]').forEach(b=>b.onclick=()=>{const i=Number(b.dataset.stage);if(route==='framework'){document.querySelectorAll('[data-stage]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)});$('#stage-panel').innerHTML=stageDetail(i)}else modal(`<div class="eyebrow">The Next Fan Framework</div><h2>${NF.stages[i].name.toUpperCase()}</h2>${stageDetail(i)}${btn('Explore the whole framework','framework','blue')}`)});
if(route==='journey'){
const stories=['Eden Hazard was the starting point of my Chelsea fandom.','The player came first. The club followed.','Watching Chelsea gave that initial interest somewhere to go.','I learned more about the team beyond one player.','The culture around the club became part of the appeal.','The club began to feel like part of my identity as a fan.','Chelsea became my team. This is my personal illustration, not academic evidence.'];document.querySelectorAll('[data-story]').forEach(b=>b.onclick=()=>{$('#story-copy').textContent=stories[b.dataset.story];document.querySelectorAll('[data-story]').forEach(x=>x.classList.toggle('active',x===b))});const paths=new Set;document.querySelectorAll('[data-path]').forEach(b=>b.onclick=()=>{paths.has(b.dataset.path)?paths.delete(b.dataset.path):paths.add(b.dataset.path);b.classList.toggle('active');b.setAttribute('aria-pressed',b.classList.contains('active'));$('#path-result').textContent=paths.size?'Your routes in: '+[...paths].join(' + ')+'. Pathways can coexist. This is your reflection, not study data.':'Your pathways will appear here. This reflection is not collected as research.'});document.querySelectorAll('[data-poll]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-poll]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$('#poll-result').textContent=`Your answer: ${b.dataset.poll}. No vote totals are being claimed. This answer stays in your current page.`});$('#quiz-form').onsubmit=e=>{e.preventDefault();const a=questions.map((_,i)=>Number($('#q'+i).value));let title,copy;if(a[0]&&a[3]&&a[9]){title='THE DIEHARD';copy='You keep showing up for the team. Even after the star leaves. That is either commitment or a very demanding hobby.'}else if(a[2]&&!a[9]){title='THE PLAYER-FIRST FAN';copy='The name on the back matters to you. Trades may require some awkward wardrobe decisions.'}else if(a[6]||a[7]){title='THE COMMUNITY FAN';copy='For you, the conversation is part of the sport. The group chat should probably have its own jersey.'}else if(a[1]&&!a[0]){title='THE HIGHLIGHT MERCHANT';copy='You prefer the condensed version. Ninety minutes? In this economy?'}else if(!a[3]&&(a[8]||a[10])){title='THE “I SWEAR I’M NOT A FAN” FAN';copy='Interesting amount of roster knowledge for someone who is just passing through.'}else if(a[2]&&!a[3]){title='THE ALGORITHM RECRUIT';copy='A player caught your attention before a team did. The nickname is playful: this quiz cannot tell how you discovered them.'}else{title='THE CASUAL';copy='You enjoy sports on your terms. There is no minimum watch-time requirement for having a good time.'}$('#quiz-result').innerHTML=`<div class="quiz-result"><div class="eyebrow">Your playful scouting report</div><h2>${title}</h2><p>${copy}</p><small>Rule-based entertainment, not scientific classification. Spending and attendance do not determine your fan worth.</small></div>`};$('#quiz-form').onreset=()=>$('#quiz-result').innerHTML='';}
if(route==='framework'){const descriptions=['Attention: a first exposure. It tells us a video was encountered, not that a fan was created.','Engagement: another view suggests continued attention in this moment. It does not show long-term attachment.','Following: a possible route back, but public post counts do not establish who followed because of this post. Outside the study’s post-level measures.','Engagement: commenting is interaction with the original post. Its meaning depends on context; it does not demonstrate deeper participation.','Participation: joining a community creates an opportunity for belonging, not proof of identity.','Viewing behavior: watching a game is a different action from watching clips. Neither determines someone’s worth as a fan.','Commercial action: a jersey purchase may express identity or simply taste. It does not validate loyalty.','Commercial action: attendance depends on geography, cost and access as well as interest.','Commercial action: stadium food is the punchline. Concession spending is not an academic measure of loyalty.','Loyalty context: returning over time and sustained attachment require separate evidence. This study does not measure them.'];document.querySelectorAll('[data-hotdog]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-hotdog]').forEach(x=>x.classList.toggle('active',x===b));$('#hotdog-detail').textContent=descriptions[b.dataset.hotdog]})}
if(route==='strategy'){$('#strategy-form').onsubmit=e=>{e.preventDefault();const chosen=[...document.querySelectorAll('input[name=assets]:checked')].map(x=>x.value);if(!chosen.length){$('#form-error').textContent='Choose at least one type of content to build your plan.';return}$('#form-error').textContent='';latestPlan=createPlan($('#org').value,$('#audience').value,$('#goal').value,chosen,$('#platform').value);$('#game-plan').innerHTML=planHtml(latestPlan);$('#export-plan').onclick=()=>download('The_Next_Fan_Game_Plan.txt',`THE NEXT FAN | JOHN GATES\nRESEARCH-INFORMED APPLICATION · NOT THESIS FINDINGS\n\nOrganization: ${latestPlan.org}\nAudience: ${latestPlan.audience}\nGoal: ${latestPlan.goal}\nPlatform: ${latestPlan.platform}\nAvailable content: ${latestPlan.chosen.join(', ')}\n\n`+latestPlan.items.map(([k,v])=>`${k.toUpperCase()}\n${v}`).join('\n\n'))};$('#strategy-form').onreset=()=>{$('#game-plan').innerHTML='';$('#form-error').textContent='';latestPlan=null}}
if(route==='lab')document.querySelectorAll('[data-format]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-format]').forEach(x=>{x.classList.toggle('active',x===b);x.setAttribute('aria-pressed',x===b)});$('#format-panel').innerHTML=formatDetail(Number(b.dataset.format))});
if(route==='film')document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>modal(`<div class="eyebrow">Application example slot / ${b.dataset.case}</div><h2>THE STORY IS STILL TO COME.</h2>${tag('No verified case study supplied')}${['Organization and source','Personality cue','Content and platform','Intended audience','Observable engagement, if verified','Creative interpretation','Proposed adaptation','Evidence and limits','JG’s take'].map(t=>`<h4>${t}</h4><p class="muted">Awaiting verified material and John’s analysis.</p>`).join('')}`));
if(route==='xi')document.querySelectorAll('[data-player]').forEach(b=>b.onclick=()=>modal(`<div class="eyebrow">John’s Starting XI / ${String(b.dataset.player).padStart(2,'0')}</div><h2>STRATEGY SLOT.</h2>${tag('This principle has not been written yet')}${['The recommendation','What the research found','Interpretation and limits','What a sports marketer could test','Observable measures','Platform adaptation','JG’s take'].map(t=>`<h4>${t}</h4><p class="muted">Waiting for John’s research data.</p>`).join('')}`));
if(route==='research')document.querySelectorAll('[data-infographic]').forEach(b=>b.onclick=()=>modal(`<div class="eyebrow">Infographic brief · evidence pending</div><h2>${b.querySelector('h3').textContent}</h2><p>Purpose: make this relationship understandable without implying that a conceptual connection is a measured result.</p><h4>Evidence needed</h4><p>A verified source, the specific supported finding and any thesis data needed to visualize it.</p><h4>Current status</h4><p>Waiting for John’s research data.</p>${btn('Inspect the provisional framework','framework','blue')}`));
if(route==='sources'){const update=()=>$('#source-results').innerHTML=sourceResults($('#source-search').value,$('#source-theme').value);$('#source-search').oninput=update;$('#source-theme').onchange=update}
if(route==='about')$('#portrait-upload').onchange=e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('image/'))return;const url=URL.createObjectURL(f);$('#portrait-preview').innerHTML=`<img src="${url}" alt="John’s selected professional portrait preview">`;$('#portrait-preview img').onload=()=>URL.revokeObjectURL(url)};
}
$('#menu').innerHTML=Object.entries(routes).map(([k,v])=>`<a href="#${k}">${v} ↗</a>`).join('');$('#menu-toggle').onclick=()=>{const open=$('#menu').hidden;$('#menu').hidden=!open;$('#menu-toggle').setAttribute('aria-expanded',open)};document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#menu').hidden=true;$('#menu-toggle').setAttribute('aria-expanded','false')}});$('#detail .close').onclick=()=>$('#detail').close();$('#detail').addEventListener('click',e=>{if(e.target===$('#detail'))$('#detail').close()});window.addEventListener('hashchange',()=>{if($('#detail').open)$('#detail').close();render()});render();
// Licensed remote images retain a source-link fallback if a host declines hotlinking.
document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const image=e.target;const figure=image.closest('figure');if(figure){const link=figure.querySelector('figcaption a');const fallback=document.createElement('a');fallback.href=link?link.href:'#sources';fallback.className='image-fallback';fallback.textContent='View the licensed photograph ↗';fallback.target='_blank';fallback.rel='noopener';image.replaceWith(fallback)}else{image.style.display='none'}},true);

